INSERT INTO `ai_playerbot_texts` (`name`, `text`, `say_type`, `reply_type`, `text_loc1`, `text_loc2`, `text_loc3`, `text_loc4`, `text_loc5`, `text_loc6`, `text_loc7`, `text_loc8`) VALUES
('emote_stay',          'Fine.. I\'ll stay right here..',                   0, 0, '', 'Très bien.. Je reste là..',              'Na gut.. Ich bleib hier.',                  '行吧……我就待在这儿。',   '', 'Bien.. me quedo aquí..',            '', 'Ладно.. останусь здесь..'),
('emote_follow',        'Wherever you go, I\'ll follow..',                  0, 0, '', 'Où que tu ailles, je te suis..',         'Wohin du auch gehst, ich folge dir..',      '不管你去哪，我都跟着。', '', 'Donde vayas, te sigo..',            '', 'Куда ты, туда и я..'),
('emote_wave',          'Hey there!',                                       0, 0, '', 'Salut!',                                 'Hey!',                                      '嘿，你好！',             '', '¡Hola!',                            '', 'Привет!'),
('emote_dance',         'Shake what your mama gave you!',                   0, 0, '', 'Bouge ce que ta mère t\'a donné!',       'Zeig, was Mama dir mitgegeben hat!',        '抖起来吧！',             '', '¡Mueve lo que te dio tu mamá!',     '', 'Танцуй как умеешь!'),
('emote_flirt',         'Awwwww...',                                        0, 0, '', 'Awwwww...',                              'Awwwww...',                                 '哇哦……',                '', 'Awwwww...',                         '', 'Ах ты мой хороший...'),
('emote_flex',          'Hercules! Hercules!',                              0, 0, '', 'Hercule! Hercule!',                      'Herkules! Herkules!',                       '大力神！大力神！',        '', '¡Hércules! ¡Hércules!',             '', 'Геракл! Геракл!'),
('emote_angry',         'Did I do thaaaaat?',                               0, 0, '', 'C\'est moi qui ai fait ça?',             'War das... ich?',                           '这是……我干的？',         '', '¿Fui yoooo?',                       '', 'Это я сделал?..'),
('emote_fart',          'Wasn\'t me! Just sayin\'..',                       0, 0, '', 'C\'était pas moi! Je dis ça comme ça..',  'Ich war\'s nicht! Nur so gesagt..',         '不是我！就这么说说。',    '', '¡No fui yo! Solo digo..',           '', 'Это не я! Просто говорю..'),
('emote_joke',          'Oh.. was I not supposed to laugh so soon?',        0, 0, '', 'Oh.. je n\'étais pas censé rire si tôt?','Oh.. sollte ich noch nicht lachen?',        '哦……我是不是笑得太早了？','', '¿No debía reírme tan pronto?',      '', 'Ой.. я слишком рано засмеялся?'),
('emote_chicken',       'We\'ll see who\'s chicken soon enough!',           0, 0, '', 'On verra bien qui est le lâche!',        'Wir werden sehen, wer der Feigling ist!',   '看谁才是懦夫！',         '', '¡Ya veremos quién es el cobarde!',  '', 'Посмотрим кто из нас трус!'),
('emote_apologize',     'You damn right you\'re sorry!',                    0, 0, '', 'Tu as raison d\'être désolé!',           'Du bist verdammt nochmal zu Recht sorry!',  '你道歉是应该的！',        '', '¡Y tanto que lo sientes!',          '', 'Ещё бы ты не извинялся!'),
('emote_applaud',       'Thank you.. Thank you.. I\'m here all week.',      0, 0, '', 'Merci.. Merci.. Je suis là toute la semaine.', 'Danke.. Danke.. Ich bin die ganze Woche hier.', '谢谢……我这周都在。', '', 'Gracias.. estoy aquí toda la semana.', '', 'Спасибо.. Спасибо.. Я здесь всю неделю.'),
('emote_beg',           'Beg all you want.. I have nothing for you.',       0, 0, '', 'Implore tant que tu veux.. je n\'ai rien pour toi.', 'Bettele so viel du willst.. ich hab nichts für dich.', '随便求吧……我没什么给你。', '', 'Suplica lo que quieras.. no tengo nada para ti.', '', 'Проси сколько хочешь.. у меня для тебя ничего нет.'),
('emote_bite',          'OUCH! Dammit, that hurt!',                        0, 0, '', 'AÏÏE! Putain, ça fait mal!',             'AUTSCH! Verdammt, das hat wehgetan!',       '哎哟！妈的，好疼！',      '', '¡AY! ¡Maldición, eso dolió!',       '', 'АЙ! Чёрт, больно!'),
('emote_bored',         'My job description doesn\'t include entertaining you..', 0, 0, '', 'Mon descriptif de poste n\'inclut pas de te divertir..', 'In meiner Stellenbeschreibung steht nichts von Unterhaltung..', '我的职责里不包括逗你开心。', '', 'Mi descripción de trabajo no incluye entretenerte..', '', 'В мои обязанности не входит тебя развлекать..'),
('emote_brb',           'Looks like time for an AFK break..',               0, 0, '', 'On dirait qu\'il est temps de faire une pause..',  'Sieht nach AFK-Pause aus..', '好像是时候摸鱼了……', '', 'Parece que es hora de un descanso AFK..', '', 'Похоже, время для АФК-перерыва..'),
('emote_agree',         'At least SOMEONE agrees with me!',                 0, 0, '', 'Au moins QUELQU\'UN est d\'accord avec moi!', 'Wenigstens JEMAND stimmt mir zu!', '终于有人同意我了！', '', '¡Al menos ALGUIEN está de acuerdo conmigo!', '', 'Хоть кто-то со мной согласен!'),
('emote_amaze',         'Yes, Yes. I know I\'m amazing..',                  0, 0, '', 'Oui, oui. Je sais que je suis incroyable..', 'Ja, ja. Ich weiß, dass ich erstaunlich bin..', '是的，我知道我很厉害……', '', 'Sí, sí. Sé que soy increíble..', '', 'Да, да. Знаю, что я великолепен..'),
('emote_bleed',         'MEDIC! Stat!',                                     0, 0, '', 'MÉDIC! Vite!',                           'SANITÄTER! Sofort!',                        '医疗兵！快！',           '', '¡MÉDICO! ¡Rápido!',                 '', 'МЕДИК! Срочно!'),
('emote_blink',         'What? You got something in your eye?',             0, 0, '', 'Quoi? T\'as quelque chose dans l\'oeil?', 'Was? Hast du was im Auge?',                '什么？你眼睛里有东西？',  '', '¿Qué? ¿Tienes algo en el ojo?',     '', 'Что? Что-то в глаз попало?'),
('emote_bounce',        'Who\'s a good doggy? You\'re a good doggy!',       0, 0, '', 'Qui est un bon chien-chien? C\'est toi!', 'Wer ist ein braves Hündchen? Du bist es!', '谁是乖狗狗？是你！',      '', '¿Quién es un buen perrito? ¡Tú lo eres!', '', 'Кто хороший песик? Ты хороший песик!'),
('emote_bye',           'Umm.... wait! Where are you going?!',              0, 0, '', 'Euh.... attends! Où tu vas?!',           'Ähm.... warte! Wo gehst du hin?!',          '呃……等等！你去哪儿？！',  '', 'Eeem.... ¡espera! ¿Adónde vas?!',   '', 'Эм.... подожди! Ты куда?!'),
('emote_laugh',         'Wait... what are we laughing at again?',           0, 0, '', 'Attends... on riait de quoi déjà?',      'Warte... worüber lachen wir nochmal?',      '等等……我们在笑什么来着？', '', 'Espera... ¿de qué nos reímos?',     '', 'Подождите... над чем мы смеёмся?'),
('emote_confused',      'Don\'t look at me.. I just work here',             0, 0, '', 'Ne me regardez pas.. je travaille juste ici.', 'Schau mich nicht an.. ich arbeite hier nur.', '别看我……我只是在这干活。', '', 'No me mires.. solo trabajo aquí.', '', 'Не смотри на меня.. я просто тут работаю.'),
('emote_cough',         'Ewww! Keep your nasty germs over there!',          0, 0, '', 'Beurk! Garde tes vilains microbes là-bas!', 'Igitt! Behalte deine ekligen Keime drüben!', '呕！把你的细菌带走！', '', '¡Puaj! ¡Quédate con tus gérmenes!', '', 'Фу! Держи своих микробов при себе!'),
('emote_cry',           'Don\'t you start crying or it\'ll make me start crying!', 0, 0, '', 'Ne commence pas à pleurer ou ça va me faire pleurer!', 'Fang bloß nicht an zu weinen, sonst muss ich auch weinen!', '你别哭，不然我也要哭了！', '', '¡No llores o me harás llorar a mí!', '', 'Не плачь, а то и я заплачу!'),
('emote_crack',         'It\'s clobbering time!',                           0, 0, '', 'C\'est l\'heure de défoncer!',           'Es ist Zeit zum Verprügeln!',               '开打时间！',             '', '¡Es la hora de la paliza!',         '', 'Время крушить!'),
('emote_eat',           'I hope you brought enough for the whole class...',  0, 0, '', 'J\'espère que tu en as apporté pour tout le monde...', 'Ich hoffe, du hast genug für alle mitgebracht...', '希望你带够了全班的份儿……', '', 'Espero que hayas traído suficiente para todos...', '', 'Надеюсь, ты принёс на всех...'),
('emote_gloat',         'Doesn\'t mean you need to be an ass about it..',   0, 0, '', 'Ça ne t\'autorise pas à te comporter comme un imbécile..', 'Das ist noch kein Grund, ein Idiot zu sein..', '不代表你就能这样……', '', 'No significa que tengas que ser un idiota..', '', 'Это не значит, что надо выпендриваться..'),
('emote_hungry',        'What? You want some of this?',                     0, 0, '', 'Quoi? Tu en veux?',                      'Was? Du willst was davon?',                 '什么？你想要点？',        '', '¿Qué? ¿Quieres un poco?',           '', 'Что? Хочешь попробовать?'),
('emote_tired',         'Is it break time already?',                        0, 0, '', 'C\'est déjà l\'heure de la pause?',      'Ist schon Pause?',                          '已经可以休息了吗？',      '', '¿Ya es la hora del descanso?',      '', 'Уже перерыв?'),
('emote_sexy',          'Keep it in your pants, boss..',                    0, 0, '', 'Garde ça pour toi, patron..',            'Halt die Hose, Boss..',                     '控制一下，大佬……',       '', 'Contrólate, jefe..',                '', 'Придержи коней, босс..'),
('emote_no',            'Aww.... why not?!',                                0, 0, '', 'Aww.... pourquoi pas?!',                 'Aww.... warum nicht?!',                     '哎……为什么不行啊？！',   '', 'Aww.... ¿por qué no?!',             '', 'Ну почему нет?!'),
('emote_panic',         'Now is NOT the time to panic!',                    0, 0, '', 'C\'est PAS le moment de paniquer!',      'Jetzt ist NICHT die Zeit für Panik!',       '现在不是恐慌的时候！',    '', '¡Ahora NO es el momento de entrar en pánico!', '', 'Сейчас НЕ время паниковать!'),
('emote_point',         'What?! I can do that TOO!',                        0, 0, '', 'Quoi?! Moi aussi je peux faire ça!',     'Was?! Das kann ich AUCH!',                  '什么？！我也会！',        '', '¡¿Qué?! ¡Yo también puedo hacer eso!', '', 'Что?! Я тоже так умею!'),
('emote_rude',          'Right back at you, bub!',                          0, 0, '', 'Je te retourne ça, mon pote!',           'Gleichfalls, Kumpel!',                      '原话奉还！',             '', '¡Lo mismo digo, amigo!',            '', 'Взаимно, приятель!'),
('emote_roar',          'RAWR!',                                            0, 0, '', 'RAWR!',                                  'RAWR!',                                     '嗷！',                  '', '¡RAWR!',                            '', 'РРААР!'),
('emote_say_stuck',     'I\'m just waiting for the ominous music now...',   0, 0, '', 'J\'attends juste la musique dramatique maintenant...', 'Ich warte nur noch auf die Unheils-Musik...', '就等那首不祥的音乐了……', '', 'Solo espero la música ominosa ahora...', '', 'Жду зловещей музыки...'),
('emote_say_nope',      'Noooooooo.. you just couldn\'t ask for directions, huh?', 0, 0, '', 'Nooooon.. tu pouvais pas demander ton chemin, hein?', 'Neeeein.. konntest du nicht einfach fragen?', '不不不……就不能问路吗？', '', 'Nooooo.. no podías pedir indicaciones, ¿eh?', '', 'Нееет.. не мог просто спросить дорогу?'),
('emote_say_genius',    'Oh boy.. another genius idea...',                  0, 0, '', 'Oh la la.. encore une idée de génie...', 'Oh Gott.. wieder eine Genieidee...', '哦天……又一个天才主意……', '', 'Vaya.. otra idea genial...', '', 'Ну надо же.. ещё одна гениальная идея...'),
('emote_say_nothanks',  'No thanks.. I had some back at the last village',  0, 0, '', 'Non merci.. j\'en avais dans le dernier village.', 'Nein danke.. hatte ich schon im letzten Dorf.', '不用了……上个村子我刚吃过。', '', 'No gracias.. tuve en la última aldea.', '', 'Нет спасибо.. в прошлой деревне уже было.'),
('emote_say_dog',       'Do I look like a dog to you?!',                   0, 0, '', 'Je ressemble à un chien?!',              'Sehe ich aus wie ein Hund?!',               '我看起来像条狗吗？！',    '', '¿Parezco un perro?!',               '', 'Я что, похож на собаку?!'),
('emote_say_eyes',      'Keep doing that and I\'ll roll those eyes right out of your head..', 0, 0, '', 'Continue comme ça et tes yeux vont sortir de ta tête..', 'Mach das weiter und deine Augen fallen dir raus..', '再这样我就把你眼珠子抠出来……', '', 'Sigue así y te sacaré los ojos de la cabeza..', '', 'Ещё раз так сделаешь — вытащу глаза из орбит..'),
('emote_say_lovely',    'Lovely... just lovely..',                          0, 0, '', 'Charmant... vraiment charmant..',        'Wunderbar... einfach wunderbar..',          '真好……真的很好……',       '', 'Encantador... simplemente encantador..',  '', 'Прекрасно... просто прекрасно..'),
('emote_say_help',      'You think that\'s going to help you?!',            0, 0, '', 'Tu crois vraiment que ça va t\'aider?!', 'Du glaubst wirklich, das hilft dir?!',      '你觉得这有用？！',        '', '¡¿Crees que eso te va a ayudar?!',   '', 'Думаешь, это тебе поможет?!');
